-- Each of the eleven kinds, on each of its three channels, reaches exactly
-- the channels chosen: supabase/notification_prefs.sql's push_collect (the
-- push), claim_comment_digest (the day's email) and notification_count_kept
-- (the bell's count), tried inside the rolled-back transaction of a dry
-- run. Nothing here is kept.
--
--   set -a; . ./.env; set +a
--   PG_MODULE=/tmp/pg/node_modules/pg/lib/index.js \
--     node tools/apply_sql.mjs supabase/notification_prefs.sql --dry \
--       --try=tools/notification_prefs_matrix_try.sql --table=notification_prefs
--
-- notification_rows is stood in for, inside the transaction only, by one
-- row of every kind the page has (fourteen, the eleven chosen kinds'),
-- each a minute old, for a made-up account with a device turned on ten
-- minutes ago, and one more comment on a model she muted. Two rounds: in
-- the first each channel has the kinds of an even place on it and the odd
-- off, in the second the other way round, so every kind is tried on and off
-- on every channel. What each round chose and what came is said side by
-- side, and whether they are the same. Each statement is on one line: the
-- dry run splits at a semicolon that ends a line.
insert into auth.users (id, instance_id, aud, role, email) values ('00000000-0000-4000-8000-0000000017c1', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'inbox-matrix@resend.dev');
select public.answer_age('00000000-0000-4000-8000-0000000017c1', true)->>'over_13' as over_13;
insert into public.shared_models (id, owner, name, author, parts, bytes, listed, listed_at, test, created_at, has_image) values ('InboxMat01', '00000000-0000-4000-8000-0000000017c1', 'Matrix tower', null, 12, 100, true, now() - interval '3 days', true, now() - interval '3 days', true), ('InboxMat02', '00000000-0000-4000-8000-0000000017c1', 'Matrix muted', null, 8, 100, true, now() - interval '2 days', true, now() - interval '2 days', true);
insert into auth.sessions (id, user_id) values ('00000000-0000-4000-8000-0000000017e2', '00000000-0000-4000-8000-0000000017c1');
insert into public.push_subscriptions (endpoint, account, p256dh, auth, origin, lang, made_at, session) values ('https://updates.push.services.mozilla.com/wpush/v2/inbox-matrix', '00000000-0000-4000-8000-0000000017c1', 'BAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA', 'AAAAAAAAAAAAAAAAAAAAAA', 'https://brickworks.diy', 'en', now() - interval '10 minutes', '00000000-0000-4000-8000-0000000017e2');
create or replace function public.notification_rows(viewer uuid, since timestamptz, until timestamptz) returns table (kind text, at timestamptz, model text, item jsonb) language sql stable as $f$ select r.kind, now() - interval '1 minute', r.model, r.item from (values ('comment', 'InboxMat01', '{"comment": 1, "model": "InboxMat01", "name": "Matrix tower"}'::jsonb), ('reply', 'InboxMat01', '{"comment": 2, "model": "InboxMat01", "name": "Matrix tower"}'::jsonb), ('mention', 'InboxMat01', '{"comment": 3, "model": "InboxMat01", "name": "Matrix tower"}'::jsonb), ('talk_mention', null, '{"thread": 7, "post": 71, "title": "Matrix thread"}'::jsonb), ('photo', 'InboxMat01', '{"photo": "p1", "model": "InboxMat01", "yours": true}'::jsonb), ('remix', 'InboxMat01', '{"model": "RemixMat01", "of": "InboxMat01", "name": "Matrix remix", "of_name": "Matrix tower"}'::jsonb), ('likes', 'InboxMat01', '{"model": "InboxMat01", "likes": 2, "day": "2026-11-23"}'::jsonb), ('talk_reply', null, '{"thread": 8, "post": 81, "title": "Matrix followed"}'::jsonb), ('challenge_open', null, '{"challenge": 5, "title": "Matrix open"}'::jsonb), ('challenge_closing', null, '{"challenge": 6, "title": "Matrix closing"}'::jsonb), ('result', 'InboxMat01', '{"challenge": 9, "model": "InboxMat01", "title": "Matrix entered"}'::jsonb), ('challenge_won', null, '{"challenge": 10, "title": "Matrix voted"}'::jsonb), ('achievement', null, '{"track": "listed", "level": 1}'::jsonb), ('announcement', null, '{"announcement": 4, "title": "Matrix news"}'::jsonb), ('comment', 'InboxMat02', '{"comment": 11, "model": "InboxMat02", "name": "Matrix muted"}'::jsonb)) r(kind, model, item) where viewer = '00000000-0000-4000-8000-0000000017c1' and now() - interval '1 minute' > since and now() - interval '1 minute' <= until $f$;
create temp table matrix (round int, channel text, chosen text, got text);
create function pg_temp.round(r int) returns void language plpgsql as $f$ declare k text[] := public.notification_kinds(); here text[]; pushed text[]; mailed text[]; mailable text[]; got_push text; got_mail text; counted int; pushes jsonb; mails jsonb; leaked int; begin here := array(select k[i] from generate_subscripts(k, 1) i where (i + r) % 2 = 0); pushed := array(select k[i] from generate_subscripts(k, 1) i where (i + r + 1) % 2 = 0); mailable := array(select x from unnest(k) x where x = any (public.notification_mailed_here())); mailed := array(select mailable[i] from generate_subscripts(mailable, 1) i where (i + r) % 2 = 0); delete from public.notification_prefs where account = '00000000-0000-4000-8000-0000000017c1'; insert into public.notification_prefs (account, here, push, email, email_since, muted) values ('00000000-0000-4000-8000-0000000017c1', here, pushed, mailed, now() - interval '1 hour', array['InboxMat02']); delete from public.push_sent where account = '00000000-0000-4000-8000-0000000017c1'; delete from public.comment_digests where owner = '00000000-0000-4000-8000-0000000017c1'; pushes := public.push_collect('00000000-0000-4000-8000-0000000017c1', 0); mails := public.claim_comment_digest('00000000-0000-4000-8000-0000000017c1'); select string_agg(distinct public.notification_kind(x->>'kind'), ',' order by public.notification_kind(x->>'kind')) into got_push from jsonb_array_elements(pushes->'devices') d, jsonb_array_elements(d->'rows') x; select string_agg(distinct public.notification_kind(n->>'kind'), ',' order by public.notification_kind(n->>'kind')) into got_mail from jsonb_array_elements(mails) d, jsonb_array_elements(d->'notices') n; select count(*) into leaked from (select x from jsonb_array_elements(pushes->'devices') d, jsonb_array_elements(d->'rows') x where x->>'on' = 'InboxMat02' union all select n from jsonb_array_elements(mails) d, jsonb_array_elements(d->'notices') n where n->>'on' = 'InboxMat02') l; select public.notification_count_kept('00000000-0000-4000-8000-0000000017c1') into counted; insert into matrix values (r, 'push', (select string_agg(x, ',' order by x) from unnest(pushed) x), coalesce(got_push, '')), (r, 'email', (select string_agg(x, ',' order by x) from unnest(mailed) x), coalesce(got_mail, '')), (r, 'here (count)', (select count(*)::text from public.notification_rows('00000000-0000-4000-8000-0000000017c1', now() - interval '1 day', now()) x where public.notification_kind(x.kind) = any (here) and x.model is distinct from 'InboxMat02'), counted::text), (r, 'muted model, pushed or mailed', '0', leaked::text); end $f$;
select pg_temp.round(0);
select pg_temp.round(1);
select round, channel, chosen, got, chosen = got as exactly from matrix order by round, channel;
-- Nothing of the muted model anywhere: its comment was a kind on in both rounds' push or here.
select (select count(*) from matrix where chosen <> got) as "rounds where what came was not what was chosen (0)", (select got from matrix where channel like 'muted%' and round = 0) || ', ' || (select got from matrix where channel like 'muted%' and round = 1) as "the muted model's rows pushed or mailed, each round (0, 0)";
-- Every kind was on and off on every channel (each channel's two rounds together hold all its kinds).
select channel, (select string_agg(x, ',' order by x) from (select distinct unnest(string_to_array(m.chosen, ',')) x from matrix m where m.channel = c.channel and m.chosen <> '') y) as "chosen over both rounds" from (select distinct channel from matrix where channel <> 'here (count)') c;
